  --lab-border: rgba(243, 231, 217, 0.12);
  --lab-border-strong: rgba(243, 231, 217, 0.22);
  --lab-shadow: 0 20px 44px rgba(0, 0, 0, 0.28);
}

html,
body {
  background: radial-gradient(circle at top, rgba(197, 138, 42, 0.08), transparent 30%),
    url("/img/lab/texture-grain.svg"),
    linear-gradient(180deg, var(--lab-bg) 0%, var(--lab-paper) 100%);
  background-size: auto, 280px 280px, auto;
}

body {
  font-family: var(--lab-sans);
  color: var(--lab-ink);
  letter-spacing: 0.01em;
  line-height: 1.75;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-weight: 700;
  letter-spacing: 0.01em;
}

p,
li {
  color: var(--lab-muted);
}

a {
  color: var(--lab-olive);
  transition: color var(--lab-fast) var(--lab-ease), opacity var(--lab-fast) var(--lab-ease), transform var(--lab-fast) var(--lab-ease);
}

a:hover {
  color: var(--lab-amber);
  text-decoration: none;
}

img {
  border-radius: var(--lab-radius-md);
}

::selection {
  background: var(--lab-amber-soft);
}

hr {
  border-top: 1px solid var(--lab-border);
}

#board {
  margin-top: -6rem;
  border-radius: 34px 34px 0 0;
  border: 1px solid var(--lab-border);
  background: linear-gradient(180deg, rgba(251, 247, 240, 0.96), rgba(246, 240, 230, 0.98));
  box-shadow: var(--lab-shadow);
  overflow: hidden;
}

html[data-user-color-scheme="dark"] #board {
  background: linear-gradient(180deg, rgba(34, 26, 21, 0.94), rgba(24, 18, 15, 0.98));
}

.lab-home-board {
  position: relative;
  margin-top: -8rem;
  isolation: isolate;
}

.lab-home-board::before {
  content: "";
  position: absolute;
  top: 0;
  left: 8%;
  right: 8%;
  height: 8rem;
  transform: translateY(-58%);
  border-radius: 999px;
  background: radial-gradient(circle, rgba(244, 219, 168, 0.32) 0%, rgba(244, 219, 168, 0.1) 42%, transparent 74%);
  filter: blur(12px);
  pointer-events: none;
  z-index: 0;
}

.lab-home-board > .container {
  position: relative;
  z-index: 1;
}

.container,
.container-fluid,
.post-content,
.markdown-body {
  max-width: min(100%, var(--lab-content));
}

#navbar {
  backdrop-filter: blur(18px) saturate(1.1);
  background: rgba(32, 24, 18, 0.22);
  border-bottom: 1px solid transparent;
  transition: background var(--lab-mid) var(--lab-ease), border-color var(--lab-mid) var(--lab-ease), box-shadow var(--lab-mid) var(--lab-ease);
}

#navbar.is-scrolled {
  background: rgba(32, 24, 18, 0.86);
  border-color: rgba(255, 255, 255, 0.08);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.18);
}

.lab-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.9rem;
  color: #fff;
}

.lab-brand-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 3.4rem;
  min-height: 3.4rem;
  border-radius: 1.35rem;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 249, 241, 0.1);
  font-family: var(--lab-serif);
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.lab-brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.lab-brand-copy strong {
  font-size: 1.14rem;
  font-weight: 700;
  letter-spacing: 0.05em;
}

.lab-brand-copy small {
  margin-top: 0.2rem;
  font-size: 0.72rem;
  color: rgba(255, 244, 230, 0.6);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

#navbar .nav-link {
  color: rgba(255, 245, 232, 0.88);
}

#navbar .nav-link:hover,
#navbar .nav-link.active {
  color: #fff;
}

body.page-home #banner,
body.page-home .banner {
  min-height: calc(100svh - 1px);
}

#banner .mask {
  background: linear-gradient(180deg, rgba(20, 15, 12, 0.3), rgba(20, 15, 12, 0.58));
}

.banner-text--home {
  width: min(100%, var(--lab-content));
  margin: 0 auto;
  padding: 0 1.5rem;
}

.lab-hero {
  position: relative;
  max-width: 46rem;
  padding: clamp(1.8rem, 3vw, 2.8rem);
  border: 1px solid rgba(255, 244, 232, 0.14);
  border-radius: 2rem;
  background: linear-gradient(145deg, rgba(24, 18, 14, 0.86), rgba(24, 18, 14, 0.6));
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.22);
  backdrop-filter: blur(14px) saturate(1.06);
  color: #fff8f1;
  overflow: hidden;
}

.lab-hero::before {
  content: "";
  position: absolute;
  inset: 0 auto auto 0;
  width: 44%;
  height: 44%;
  background: radial-gradient(circle, rgba(244, 219, 168, 0.18), transparent 72%);
  pointer-events: none;
}

.lab-hero-eyebrow,
.lab-kicker {
  margin-bottom: 1rem;
  color: var(--lab-amber);
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.lab-hero-title {
  margin: 0;
  color: #fff8f1;
  font-size: clamp(2.8rem, 5vw, 5.5rem);
  line-height: 1.01;
  max-width: 10ch;
  position: relative;
  z-index: 1;
}

.lab-hero-summary {
  margin: 1.6rem 0 0;
  max-width: 32rem;
  color: rgba(255, 244, 232, 0.88);
  font-size: 1.05rem;
  position: relative;
  z-index: 1;
}

.lab-post-hero {
  width: min(100%, 62rem);
  margin: 0 auto;
  padding: clamp(0.5rem, 2vw, 1rem) 1.5rem 0;
  text-align: left;
}

.lab-post-hero-kicker {
  margin: 0 0 1rem;
  color: rgba(255, 238, 212, 0.72);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.lab-post-hero-title {
  margin: 0;
  color: #fff8f1;
  font-size: clamp(3rem, 6vw, 6rem);
  line-height: 0.96;
  letter-spacing: 0.02em;
  text-wrap: balance;
  text-shadow: 0 16px 40px rgba(0, 0, 0, 0.24);
}

.lab-post-hero-dek {
  max-width: 36rem;
  margin: 1.4rem 0 0;
  color: rgba(255, 244, 232, 0.82);
  font-size: 1.02rem;
  line-height: 1.9;
}

.lab-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin-top: 2rem;
  position: relative;
  z-index: 1;
}

.lab-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3.1rem;
  padding: 0 1.3rem;
  border-radius: 999px;
  border: 1px solid transparent;
  font-weight: 600;
  transition: transform var(--lab-fast) var(--lab-ease), box-shadow var(--lab-fast) var(--lab-ease), background var(--lab-fast) var(--lab-ease), color var(--lab-fast) var(--lab-ease);
}

.lab-button--primary {
  background: var(--lab-amber);
  color: #fffaf1;
  box-shadow: 0 12px 28px rgba(197, 138, 42, 0.28);
}

.lab-button--secondary {
  border-color: rgba(255, 244, 232, 0.18);
  background: rgba(255, 250, 241, 0.16);
  color: #fff8f1;
}

.lab-button:hover {
  transform: translateY(-2px);
}

.lab-button--primary:hover {
  color: #fffaf1;
  box-shadow: 0 16px 34px rgba(197, 138, 42, 0.34);
}

.lab-button--secondary:hover {
  color: #fff8f1;
  background: rgba(255, 250, 241, 0.2);
}

.lab-section {
  position: relative;
  padding: 4.5rem 0;
}

.lab-section + .lab-section {
  padding-top: 5.4rem;
  border-top: 0;
}

.lab-section + .lab-section::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(74, 56, 39, 0.18) 16%, rgba(74, 56, 39, 0.32) 50%, rgba(74, 56, 39, 0.18) 84%, transparent);
}

.lab-section + .lab-section::after {
  content: "";
  position: absolute;
  top: -0.36rem;
  left: 50%;
  width: 0.72rem;
  height: 0.72rem;
  margin-left: -0.36rem;
  border-radius: 50%;
  border: 1px solid rgba(197, 138, 42, 0.44);
  background: var(--lab-paper);
  box-shadow: 0 0 0 7px rgba(197, 138, 42, 0.08);
}

.lab-section-heading {
  max-width: 44rem;
  margin-bottom: 2rem;
}

.lab-section-heading h2 {
  margin-bottom: 0.9rem;
  font-size: clamp(1.8rem, 2.8vw, 3rem);
  line-height: 1.08;
}

.lab-section-heading p {
  margin-bottom: 0;
  font-size: 1rem;
}

.lab-featured {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  gap: 2rem;
  align-items: stretch;
}

.lab-home-bridge {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin: 0.8rem 0 1rem;
  opacity: 0.92;
}

.lab-home-bridge-line {
  width: clamp(4.5rem, 10vw, 8rem);
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(74, 56, 39, 0.28), rgba(197, 138, 42, 0.34), transparent);
}

.lab-home-bridge-mark {
  position: relative;
  width: 2.6rem;
  height: 2.6rem;
  border-radius: 50%;
  border: 1px solid rgba(74, 56, 39, 0.16);
  background: radial-gradient(circle at 50% 50%, rgba(197, 138, 42, 0.2), rgba(197, 138, 42, 0.04) 56%, transparent 58%);
  box-shadow: inset 0 0 0 0.4rem rgba(255, 255, 255, 0.2);
}

.lab-home-bridge-mark::before,
.lab-home-bridge-mark::after {
  content: "";
  position: absolute;
  border-radius: 50%;
}

.lab-home-bridge-mark::before {
  inset: 0.72rem;
  background: rgba(197, 138, 42, 0.46);
}

.lab-home-bridge-mark::after {
  inset: 0.34rem;
  border: 1px dashed rgba(197, 138, 42, 0.26);
}

.lab-featured-media img,
.lab-post-item-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border: 1px solid var(--lab-border);
  box-shadow: var(--lab-shadow);
}

.lab-featured-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 1rem 0;
}

.lab-featured-date,
.lab-post-item-meta,
.lab-timeline-item time {
  color: var(--lab-muted);
  font-size: 0.9rem;
  letter-spacing: 0.04em;
}

.lab-featured-content h3,
.lab-path h3,
.lab-post-item-content h3,
.evolution-stage h3,
.evolution-principles h3 {
  margin-bottom: 0.8rem;
  font-size: 2rem;
  line-height: 1.18;
}

.lab-featured-excerpt,
.lab-post-item-content p,
.lab-path p,
.lab-about-grid p {
  font-size: 1rem;
}

.lab-meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: 1.4rem;
}

.lab-chip {
  display: inline-flex;
  align-items: center;
  min-height: 2rem;
  padding: 0 0.8rem;
  border-radius: 999px;
  border: 1px solid var(--lab-border);
  background: var(--lab-paper-strong);
  color: var(--lab-olive);
  font-size: 0.9rem;
}

.lab-chip--link:hover {
  transform: translateY(-1px);
}

.lab-path-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.4rem;
}

.lab-path,
.lab-page-shell > .evolution-container > section,
.lab-post-header,
#toc,
#tocbot,
.toc-container,
.wl-card,
.wl-panel,
.wl-editor,
.wl-input {
  padding: 1.6rem;
  border-radius: var(--lab-radius-md);
  border: 1px solid var(--lab-border);
  background: rgba(251, 247, 240, 0.78);
  box-shadow: var(--lab-shadow);
}

html[data-user-color-scheme="dark"] .lab-path,
html[data-user-color-scheme="dark"] .lab-page-shell > .evolution-container > section,
html[data-user-color-scheme="dark"] .lab-post-header,
html[data-user-color-scheme="dark"] #toc,
html[data-user-color-scheme="dark"] #tocbot,
html[data-user-color-scheme="dark"] .toc-container,
html[data-user-color-scheme="dark"] .wl-card,
html[data-user-color-scheme="dark"] .wl-panel,
html[data-user-color-scheme="dark"] .wl-editor,
html[data-user-color-scheme="dark"] .wl-input {
  background: rgba(34, 26, 21, 0.76);
}

.lab-path-links {
  margin: 1.1rem 0 0;
  padding-left: 1.1rem;
}

.lab-path-links li + li {
  margin-top: 0.55rem;
}

.lab-recent-list {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.lab-post-item {
  position: relative;
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  gap: 1.55rem;
  align-items: stretch;
  padding: 1.35rem;
  border: 1px solid var(--lab-border);
  border-radius: 28px;
  background: linear-gradient(135deg, rgba(255, 251, 245, 0.92), rgba(246, 240, 230, 0.9));
  box-shadow: var(--lab-shadow);
  overflow: hidden;
}

.lab-post-item::before {
  content: "";
  position: absolute;
  top: 1rem;
  bottom: 1rem;
  left: 0;
  width: 5px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(197, 138, 42, 0.86), rgba(197, 138, 42, 0.26));
}

.lab-post-item::after {
  content: "";
  position: absolute;
  top: 1.1rem;
  right: 1.25rem;
  width: 4.8rem;
  height: 4.8rem;
  border-radius: 50%;
  background:
    radial-gradient(circle at 30% 35%, rgba(197, 138, 42, 0.24) 0.2rem, transparent 0.24rem),
    radial-gradient(circle at 68% 32%, rgba(65, 83, 70, 0.2) 0.18rem, transparent 0.22rem),
    radial-gradient(circle at 54% 72%, rgba(197, 138, 42, 0.18) 0.22rem, transparent 0.28rem);
  opacity: 0.9;
  pointer-events: none;
}

.lab-post-item-media {
  display: block;
  overflow: hidden;
  border-radius: var(--lab-radius-md);
  height: 100%;
}

.lab-post-item-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.45rem;
  padding: 0.2rem 0 0.1rem;
}

.lab-post-item-content h3 {
  font-size: 1.45rem;
  margin-bottom: 0.35rem;
}

.lab-post-item-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  margin-bottom: 0.4rem;
}

.lab-post-item-meta > * {
  display: inline-flex;
  align-items: center;
  min-height: 2rem;
  padding: 0 0.72rem;
  border-radius: 999px;
  border: 1px solid var(--lab-border);
  background: rgba(255, 255, 255, 0.46);
}

.lab-section--recent::before {
  content: "";
  position: absolute;
  top: 1.6rem;
  right: 0;
  width: 10rem;
  height: 1px;
  background: linear-gradient(90deg, rgba(197, 138, 42, 0), rgba(197, 138, 42, 0.28), rgba(197, 138, 42, 0));
}

html[data-user-color-scheme="dark"] .lab-post-item {
  background: linear-gradient(135deg, rgba(42, 33, 27, 0.9), rgba(30, 23, 18, 0.92));
}

html[data-user-color-scheme="dark"] .lab-post-item-meta > * {
  background: rgba(255, 255, 255, 0.06);
}

.lab-about-grid {
  display: grid;
  gap: 1rem;
}

.lab-inline-link {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  font-weight: 700;
}

.lab-listing {
  padding-top: 4.8rem;
}

.lab-category-grid,
.lab-tag-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.2rem;
}

.lab-category-card,
.lab-tag-card,
.lab-category-sidebar-group {
  border-radius: var(--lab-radius-md);
  border: 1px solid var(--lab-border);
  background: rgba(251, 247, 240, 0.82);
  box-shadow: var(--lab-shadow);
}

html[data-user-color-scheme="dark"] .lab-category-card,
html[data-user-color-scheme="dark"] .lab-tag-card,
html[data-user-color-scheme="dark"] .lab-category-sidebar-group {
  background: rgba(34, 26, 21, 0.78);
}

.lab-category-card {
  padding: 1.5rem;
}

.lab-category-card-head {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
}

.lab-category-card-head h3 {
  margin: 0;
  font-size: 1.55rem;
}

.lab-category-card-copy {
  margin: 1rem 0;
}

.lab-category-card-posts,
.lab-category-sidebar-posts {
  display: grid;
  gap: 0.7rem;
}

.lab-category-card-posts a,
.lab-category-sidebar-posts a,
.lab-tag-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  padding: 0.9rem 1rem;
  border-radius: 16px;
  border: 1px solid var(--lab-border);
  background: rgba(255, 253, 248, 0.72);
  color: var(--lab-ink);
}

html[data-user-color-scheme="dark"] .lab-category-card-posts a,
html[data-user-color-scheme="dark"] .lab-category-sidebar-posts a,
html[data-user-color-scheme="dark"] .lab-tag-card {
  background: rgba(42, 33, 27, 0.72);
}

.lab-category-card-posts a:hover,
.lab-category-sidebar-posts a:hover,
.lab-tag-card:hover {
  transform: translateY(-1px);
}

.lab-category-card-posts time,
.lab-tag-card-count,
.lab-category-sidebar-title span:last-child {
  color: var(--lab-muted);
  white-space: nowrap;
}

.lab-category-sidebar {
  display: grid;
  gap: 1rem;
}

.lab-category-sidebar-group {
  padding: 1rem;
}

.lab-category-sidebar-title {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.9rem;
  padding-bottom: 0.8rem;
  border-bottom: 1px solid var(--lab-border);
  color: var(--lab-ink);
  font-family: var(--lab-serif);
}

.lab-category-sidebar-posts a.is-active {
  border-color: var(--lab-amber);
  background: var(--lab-amber-soft);
}

.lab-tag-card-name {
  color: var(--lab-olive);
  font-weight: 700;
}

.lab-timeline {
  position: relative;
  padding-left: 2rem;
}

.lab-timeline::before {
  content: "";
  position: absolute;
  top: 0.6rem;
  bottom: 0.6rem;
  left: 0.4rem;
  width: 1px;
  background: var(--lab-border-strong);
}

.lab-timeline-year {
  position: relative;
  margin: 1.8rem 0 1rem;
}

.lab-timeline-year span {
  display: inline-flex;
  align-items: center;
  min-height: 2rem;
  padding: 0 0.75rem;
  border-radius: 999px;
  background: var(--lab-paper-strong);
  color: var(--lab-ink);
  font-weight: 700;
}

.lab-timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr);
  gap: 1rem;
  padding: 0.5rem 0 1rem;
}

.lab-timeline-item::before {
  content: "";
  position: absolute;
  top: 0.8rem;
  left: -1.86rem;
  width: 0.8rem;
  height: 0.8rem;
  border-radius: 50%;
  background: var(--lab-amber);
  box-shadow: 0 0 0 5px var(--lab-amber-soft);
}

.lab-timeline-entry {
  display: grid;
  gap: 0.7rem;
}

.lab-timeline-entry > a {
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-size: 1.18rem;
}

.lab-timeline-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
}

.lab-page-content {
  max-width: min(100%, 980px);
  margin: 0 auto;
  padding: 4rem 0 1rem;
}

.lab-page-shell {
  display: grid;
  gap: 1.4rem;
}

.evolution-container {
  display: grid;
  gap: 1.4rem;
}

.evolution-intro h2,
.evolution-focus h3,
.evolution-timeline h3,
.evolution-principles h3 {
  margin-bottom: 1rem;
}

.evolution-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.evolution-stage {
  padding: 1.3rem;
  border-radius: var(--lab-radius-sm);
  background: var(--lab-paper);
  border: 1px solid var(--lab-border);
}

.evolution-stage p {
  margin-bottom: 0;
}

.evolution-timeline-header {
  max-width: 42rem;
  margin-bottom: 2rem;
}

.evolution-timeline-header > p:last-child {
  margin-bottom: 0;
}

.evolution-history {
  display: grid;
  gap: 2rem;
}

.evolution-era {
  display: grid;
  gap: 1.1rem;
}

.evolution-era + .evolution-era {
  padding-top: 1.8rem;
  border-top: 1px solid var(--lab-border);
}

.evolution-era-label {
  display: grid;
  gap: 0.55rem;
}

.evolution-era-label span {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  min-height: 2rem;
  padding: 0 0.8rem;
  border-radius: 999px;
  background: var(--lab-amber-soft);
  color: var(--lab-amber);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.evolution-era-label h4 {
  margin: 0;
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-size: 1.5rem;
}

.evolution-era-items {
  position: relative;
  display: grid;
  gap: 1.25rem;
  padding-left: 1.6rem;
}

.evolution-era-items::before {
  content: "";
  position: absolute;
  top: 0.2rem;
  bottom: 0.2rem;
  left: 0.35rem;
  width: 1px;
  background: linear-gradient(180deg, rgba(197, 138, 42, 0.1), rgba(197, 138, 42, 0.34), rgba(74, 56, 39, 0.14));
}

.evolution-milestone {
  position: relative;
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  gap: 1.1rem;
  align-items: start;
}

.evolution-milestone::before {
  content: "";
  position: absolute;
  top: 0.55rem;
  left: -1.33rem;
  width: 0.82rem;
  height: 0.82rem;
  border-radius: 50%;
  background: var(--lab-amber);
  box-shadow: 0 0 0 5px var(--lab-amber-soft);
}

.evolution-milestone-date {
  color: var(--lab-amber);
  font-weight: 700;
  letter-spacing: 0.04em;
}

.evolution-milestone-body {
  display: grid;
  gap: 0.45rem;
  padding: 0.05rem 0 1.15rem;
  border-bottom: 1px solid rgba(74, 56, 39, 0.1);
}

.evolution-milestone:last-child .evolution-milestone-body {
  padding-bottom: 0;
  border-bottom: 0;
}

.evolution-milestone-title {
  margin: 0;
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-size: 1.22rem;
  line-height: 1.2;
}

.evolution-milestone-summary {
  margin: 0;
  color: var(--lab-muted);
}

.evolution-outlook {
  margin-top: 0.2rem;
  padding: 1.5rem;
  border-radius: var(--lab-radius-md);
  border: 1px solid rgba(197, 138, 42, 0.24);
  background: linear-gradient(135deg, rgba(197, 138, 42, 0.08), rgba(255, 255, 255, 0.26));
  box-shadow: var(--lab-shadow);
}

.evolution-outlook h4 {
  margin: 0 0 0.7rem;
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-size: 1.35rem;
}

.evolution-outlook p {
  margin: 0;
}

html[data-user-color-scheme="dark"] .evolution-outlook {
  background: linear-gradient(135deg, rgba(197, 138, 42, 0.1), rgba(42, 33, 27, 0.78));
  border-color: rgba(197, 138, 42, 0.26);
}

.evolution-principles ul {
  margin: 0;
  padding-left: 1.2rem;
}

.evolution-principles li + li {
  margin-top: 0.6rem;
}

body.page-post #board-ctn.container {
  width: min(100%, var(--lab-post-shell));
  max-width: min(100%, var(--lab-post-shell));
}

body.page-post #banner,
body.page-post .banner {
  min-height: clamp(28rem, 68vh, 42rem);
}

body.page-post #banner .mask {
  background:
    linear-gradient(180deg, rgba(18, 14, 11, 0.18) 0%, rgba(18, 14, 11, 0.5) 42%, rgba(18, 14, 11, 0.84) 100%),
    linear-gradient(135deg, rgba(197, 138, 42, 0.12), transparent 38%);
}

body.page-post .banner-text {
  width: min(100%, var(--lab-post-shell));
  margin: 0 auto;
  padding: clamp(7rem, 14vw, 10rem) 1.5rem clamp(8rem, 16vw, 11rem);
}

body.page-post #board {
  margin-top: calc(var(--lab-post-overlap) * -1);
  padding: 0 0 4rem;
  border: 0;
  border-radius: 2.8rem 2.8rem 0 0;
  background: transparent;
  box-shadow: none;
  overflow: visible;
}

body.page-post .post-content {
  max-width: min(100%, var(--lab-post-shell));
  padding: 0 1.5rem 1rem;
}

.lab-post-header {
  margin: 1.8rem 0 2.2rem;
}

body.page-post .lab-post-intro {
  position: relative;
  z-index: 2;
  width: min(100%, calc(var(--lab-post-reading) + 1rem));
  margin: 0 0 2rem;
  padding: clamp(1.35rem, 2.8vw, 2rem);
  border-radius: 2rem;
  border: 1px solid rgba(74, 56, 39, 0.12);
  background:
    linear-gradient(135deg, rgba(255, 252, 247, 0.84), rgba(244, 235, 221, 0.92)),
    url("/img/lab/texture-grain.svg");
  box-shadow: 0 18px 50px rgba(32, 24, 18, 0.08);
  backdrop-filter: blur(14px);
}

html[data-user-color-scheme="dark"] body.page-post .lab-post-intro,
html[data-user-color-scheme="dark"] .page-post .lab-post-intro {
  background:
    linear-gradient(135deg, rgba(42, 33, 27, 0.84), rgba(31, 23, 18, 0.94)),
    url("/img/lab/texture-grain.svg");
}

.lab-post-header-meta .mt-3,
.lab-post-header-meta .mt-1,
.post-metas.my-3 {
  margin: 0 !important;
}

.lab-post-header-meta {
  display: grid;
  gap: 0.85rem;
}

.lab-post-meta-line {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.lab-post-summary {
  margin: 1.1rem 0 0;
  font-size: 1.02rem;
}

body.page-post .lab-post-summary {
  max-width: 50rem;
  margin-top: 1rem;
  color: var(--lab-ink);
  font-size: 1.08rem;
  line-height: 1.92;
}

body.page-post .post-metas.my-3 {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem 1rem;
}

body.page-post .post-metas .post-meta {
  margin-right: 0;
}

body.page-post .post-metas .post-meta a {
  display: inline-flex;
  align-items: center;
  margin: 0.15rem 0.45rem 0.15rem 0;
  padding: 0.1rem 0.55rem;
  border-radius: 999px;
  background: rgba(197, 138, 42, 0.1);
  color: var(--lab-olive);
  font-size: 0.88rem;
}

body.page-post .post-metas .post-meta a:last-child {
  margin-right: 0;
}

body.page-post #updated-time {
  width: fit-content;
  margin: 0 0 1.5rem;
}

body.page-post .lab-post-body-layout {
  display: grid;
  grid-template-columns: minmax(0, var(--lab-post-reading)) minmax(220px, var(--lab-post-aside));
  gap: var(--lab-post-gap);
  align-items: start;
}

body.page-post .lab-post-main {
  min-width: 0;
}

body.page-post .lab-post-paper {
  position: relative;
  padding: clamp(1.6rem, 3vw, 2.8rem);
  border-radius: 2.2rem;
  border: 1px solid rgba(74, 56, 39, 0.12);
  background:
    linear-gradient(180deg, rgba(255, 252, 247, 0.97), rgba(248, 241, 232, 0.98)),
    url("/img/lab/texture-grain.svg");
  box-shadow: 0 18px 50px rgba(32, 24, 18, 0.08);
}

body.page-post .lab-post-paper::before {
  content: "";
  position: absolute;
  top: 1.1rem;
  left: 1.2rem;
  right: 1.2rem;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(197, 138, 42, 0.36), transparent);
  opacity: 0.72;
  pointer-events: none;
}

html[data-user-color-scheme="dark"] body.page-post .lab-post-paper,
html[data-user-color-scheme="dark"] .page-post .lab-post-paper {
  background:
    linear-gradient(180deg, rgba(37, 29, 24, 0.97), rgba(28, 21, 17, 0.98)),
    url("/img/lab/texture-grain.svg");
}

body.page-post .lab-post-tail {
  display: grid;
  gap: 1.2rem;
  margin-top: 1.6rem;
}

body.page-post .lab-post-divider {
  margin: 0.1rem 0 0;
}

body.page-post .lab-post-rail {
  min-width: 0;
}

body.page-post .lab-post-sidebar {
  position: static;
  padding: 0;
}

body.page-post .lab-seo-header {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.post-content .markdown-body,
.markdown-body {
  color: var(--lab-ink);
  font-size: 1.03rem;
  line-height: 1.92;
}

.post-content .markdown-body p,
.post-content .markdown-body li,
.markdown-body p,
.markdown-body li {
  color: var(--lab-muted);
}

.post-content .markdown-body h1,
.post-content .markdown-body h2,
.post-content .markdown-body h3,
.markdown-body h1,
.markdown-body h2,
.markdown-body h3 {
  margin-top: 2.4rem;
  margin-bottom: 1rem;
}

.markdown-body blockquote {
  margin: 1.8rem 0;
  padding: 1rem 1.2rem 1rem 1.4rem;
  border-left: 3px solid var(--lab-amber);
  background: rgba(197, 138, 42, 0.08);
  color: var(--lab-ink);
}

.markdown-body code {
  border-radius: 0.5rem;
  padding: 0.1em 0.35em;
  background: var(--lab-amber-soft);
  color: var(--lab-ink);
}

.markdown-body pre,
.markdown-body .hljs {
  border-radius: var(--lab-radius-md);
  border: 1px solid var(--lab-border);
  background: rgba(34, 26, 21, 0.95);
}

.markdown-body img {
  border: 1px solid var(--lab-border);
  box-shadow: var(--lab-shadow);
}

body.page-post #toc,
body.page-post #tocbot,
body.page-post .toc-container {
  position: sticky;
  top: 6rem;
  padding: 1.35rem 1.2rem 1.4rem;
  border-radius: 1.6rem;
  border: 1px solid rgba(74, 56, 39, 0.12);
  background: rgba(251, 247, 240, 0.58);
  box-shadow: none;
  backdrop-filter: blur(12px);
}

body.page-post #toc .toc-header {
  margin-bottom: 0.8rem;
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-weight: 700;
}

body.page-post #toc .toc-header span {
  letter-spacing: 0.08em;
}

body.page-post #toc a,
body.page-post #tocbot a,
body.page-post .toc-container a {
  color: var(--lab-muted);
}

body.page-post #toc a:hover,
body.page-post #tocbot a:hover,
body.page-post .toc-container a:hover,
body.page-post .tocbot-active-link {
  color: var(--lab-olive) !important;
}

body.page-post #toc .toc-body {
  max-height: calc(100vh - 9rem);
  padding-right: 0.2rem;
}

body.page-post #toc .toc-list-item {
  display: block;
  padding: 0.22rem 0;
  overflow: visible;
  -webkit-line-clamp: initial;
}

body.page-post #toc .tocbot-link {
  display: block;
  padding: 0.15rem 0 0.15rem 0.8rem;
  border-left: 1px solid transparent;
  font-size: 0.95rem;
  line-height: 1.55;
}

body.page-post #toc .tocbot-list ol {
  padding-left: 0.95rem;
}

body.page-post #toc .tocbot-list ol .tocbot-link {
  font-size: 0.88rem;
  opacity: 0.88;
}

body.page-post #toc .tocbot-active-link {
  border-left-color: rgba(197, 138, 42, 0.8);
  color: var(--lab-ink) !important;
  font-weight: 700;
}

body.page-post #toc .toc-list-item::before {
  left: 0.1rem;
}

body.page-post .license-box,
body.page-post .post-prevnext,
body.page-post #comments {
  border: 1px solid var(--lab-border);
  border-radius: var(--lab-radius-md);
  background: rgba(251, 247, 240, 0.78);
  box-shadow: none;
}

body.page-post .license-box,
body.page-post .post-prevnext {
  padding: 1.15rem 1.25rem;
}

body.page-post #comments {
  margin-top: 0;
  padding: 1.25rem;
}

.pagination .page-link,
#scroll-top-button {
  border-radius: 999px;
  border: 1px solid var(--lab-border);
  background: rgba(251, 247, 240, 0.92);
  color: var(--lab-ink);
}

#scroll-top-button:hover,
.pagination .page-item.active .page-link {
  background: var(--lab-amber);
  color: #fff;
  border-color: var(--lab-amber);
}

.wl-btn {
  border-radius: 999px !important;
  border-color: var(--lab-amber) !important;
  background: var(--lab-amber-soft) !important;
  color: var(--lab-ink) !important;
}

.lab-footer {
  padding: 2.5rem 1rem 3rem;
}

.lab-footer-content {
  display: grid;
  gap: 0.7rem;
  justify-items: center;
  text-align: center;
}

.lab-footer-title {
  margin: 0;
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-size: 1.1rem;
}

.lab-footer-text {
  margin: 0;
  max-width: 40rem;
}

.lab-footer-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
}

.kb-reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 520ms var(--lab-ease), transform 520ms var(--lab-ease);
}

.kb-reveal.is-inview {
  opacity: 1;
  transform: translateY(0);
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible {
  outline: 2px solid var(--lab-amber);
  outline-offset: 3px;
}

@media (max-width: 1199px) {
  #board {
    margin-top: -4rem;
  }

  .lab-featured,
  .lab-path-grid,
  .evolution-grid,
  .lab-category-grid,
  .lab-tag-grid {
    grid-template-columns: 1fr;
  }

  .lab-post-item {
    grid-template-columns: 180px minmax(0, 1fr);
  }

  body.page-post #board {
    margin-top: calc(var(--lab-post-overlap) * -0.72);
  }

  body.page-post .lab-post-body-layout {
    grid-template-columns: 1fr;
    gap: 1.4rem;
  }

  body.page-post .lab-post-rail {
    order: -1;
  }

  body.page-post #toc,
  body.page-post #tocbot,
  body.page-post .toc-container {
    position: relative;
    top: 0;
  }
}

@media (max-width: 768px) {
  body.page-home #banner,
  body.page-home .banner {
    min-height: 86svh;
  }

  #board {
    margin-top: -2.5rem;
    border-radius: 28px 28px 0 0;
  }

  .lab-home-board {
    margin-top: -3.4rem;
  }

  .lab-brand-mark {
    min-width: 3.5rem;
    min-height: 3.5rem;
    font-size: 0.82rem;
  }

  .lab-brand-copy small {
    display: none;
  }

  .lab-section {
    padding: 3.2rem 0;
  }

  .lab-post-item,
  .evolution-milestone,
  .lab-timeline-item {
    grid-template-columns: 1fr;
  }

  .lab-hero {
    padding: 1.5rem;
    border-radius: 1.6rem;
  }

  .lab-home-bridge {
    margin: 0.3rem 0 0.8rem;
    gap: 0.8rem;
  }

  .lab-home-bridge-mark {
    width: 2.2rem;
    height: 2.2rem;
  }

  .lab-section + .lab-section {
    padding-top: 4.2rem;
  }

  .lab-post-item {
    gap: 1rem;
    padding: 1rem;
  }

  .evolution-era-items {
    padding-left: 1.2rem;
  }

  .evolution-milestone {
    gap: 0.45rem;
  }

  .evolution-milestone-date {
    display: inline-flex;
    width: fit-content;
    min-height: 1.8rem;
    padding: 0 0.65rem;
    border-radius: 999px;
    background: var(--lab-amber-soft);
  }

  .evolution-milestone-body {
    padding-bottom: 1rem;
  }

  .lab-category-card-posts a,
  .lab-tag-card {
    align-items: flex-start;
    flex-direction: column;
  }

  .lab-post-item-media img {
    min-height: 220px;
  }

  .lab-page-content {
    padding-top: 2.8rem;
  }

  body.page-post #banner,
  body.page-post .banner {
    min-height: 32rem;
  }

  body.page-post .banner-text {
    padding: 6.2rem 1rem 6.4rem;
  }

  body.page-post #board {
    margin-top: -2rem;
    padding-bottom: 2.8rem;
  }

  body.page-post .post-content {
    padding: 0 1rem 1rem;
  }

  body.page-post .lab-post-intro,
  body.page-post .lab-post-paper,
  body.page-post #toc,
  body.page-post #tocbot,
  body.page-post .toc-container {
    padding: 1.25rem;
  }

  body.page-post .lab-post-hero-title {
    font-size: clamp(2.6rem, 10vw, 4rem);
  }

  body.page-post .lab-post-hero-dek {
    font-size: 0.98rem;
  }
}

@media (max-width: 480px) {
  .lab-hero-title {
    font-size: 2.5rem;
  }

  .lab-hero-actions {
    flex-direction: column;
  }

  .lab-button {
    width: 100%;
  }

  .lab-home-bridge {
    gap: 0.6rem;
  }

  .lab-home-bridge-line {
    width: 3.2rem;
  }

  .lab-post-item {
    padding: 0.95rem;
    border-radius: 24px;
  }

  .evolution-era {
    gap: 0.9rem;
  }

  .evolution-era-label h4 {
    font-size: 1.28rem;
  }

  .evolution-outlook {
    padding: 1.2rem;
  }

  .lab-hero-summary,
  .lab-post-summary,
  .lab-post-item-content p,
  .lab-path p {
    font-size: 0.96rem;
  }

  .lab-path,
  .lab-page-shell > .evolution-container > section,
  .lab-post-header,
  #toc,
  #tocbot,
  .toc-container {
    padding: 1.2rem;
  }

  body.page-post #banner,
  body.page-post .banner {
    min-height: 28rem;
  }

  body.page-post .banner-text {
    padding: 5.8rem 1rem 5.3rem;
  }

  body.page-post .lab-post-hero-title {
    font-size: 2.45rem;
  }

  body.page-post .lab-post-hero-dek,
  body.page-post .lab-post-summary {
    font-size: 0.95rem;
  }

  body.page-post .lab-post-intro,
  body.page-post .lab-post-paper,
  body.page-post #toc,
  body.page-post #tocbot,
  body.page-post .toc-container {
    padding: 1.05rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }

  .kb-reveal {
    opacity: 1 !important;
    transform: none !important;
  }
}

Page.content:
:root {
  --lab-bg: #f6f0e6;
  --lab-paper: #fbf7f0;
  --lab-paper-strong: #f3eadc;
  --lab-ink: #201812;
  --lab-muted: #6d5e53;
  --lab-amber: #c58a2a;
  --lab-amber-soft: rgba(197, 138, 42, 0.14);
  --lab-olive: #415346;
  --lab-border: rgba(74, 56, 39, 0.14);
  --lab-border-strong: rgba(74, 56, 39, 0.24);
  --lab-shadow: 0 18px 40px rgba(32, 24, 18, 0.08);
  --lab-radius-sm: 12px;
  --lab-radius-md: 22px;
  --lab-radius-lg: 34px;
  --lab-content: 1180px;
  --lab-reading: 760px;
  --lab-post-shell: 1360px;
  --lab-post-reading: 940px;
  --lab-post-aside: 250px;
  --lab-post-gap: clamp(2rem, 4vw, 4rem);
  --lab-post-overlap: clamp(3.4rem, 7vw, 5.8rem);
  --lab-serif: "Noto Serif SC", "Songti SC", "STSong", "Source Han Serif SC", serif;
  --lab-sans: "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  --lab-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --lab-fast: 180ms;
  --lab-mid: 280ms;
}

html[data-user-color-scheme="dark"] {
  --lab-bg: #18120f;
  --lab-paper: #221a15;
  --lab-paper-strong: #2a211b;
  --lab-ink: #f3e7d9;
  --lab-muted: #c2b2a2;
  --lab-amber: #d4a24f;
  --lab-amber-soft: rgba(212, 162, 79, 0.14);
  --lab-olive: #9faf9b;
  --lab-border: rgba(243, 231, 217, 0.12);
  --lab-border-strong: rgba(243, 231, 217, 0.22);
  --lab-shadow: 0 20px 44px rgba(0, 0, 0, 0.28);
}

html,
body {
  background: radial-gradient(circle at top, rgba(197, 138, 42, 0.08), transparent 30%),
    url("/img/lab/texture-grain.svg"),
    linear-gradient(180deg, var(--lab-bg) 0%, var(--lab-paper) 100%);
  background-size: auto, 280px 280px, auto;
}

body {
  font-family: var(--lab-sans);
  color: var(--lab-ink);
  letter-spacing: 0.01em;
  line-height: 1.75;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-weight: 700;
  letter-spacing: 0.01em;
}

p,
li {
  color: var(--lab-muted);
}

a {
  color: var(--lab-olive);
  transition: color var(--lab-fast) var(--lab-ease), opacity var(--lab-fast) var(--lab-ease), transform var(--lab-fast) var(--lab-ease);
}

a:hover {
  color: var(--lab-amber);
  text-decoration: none;
}

img {
  border-radius: var(--lab-radius-md);
}

::selection {
  background: var(--lab-amber-soft);
}

hr {
  border-top: 1px solid var(--lab-border);
}

#board {
  margin-top: -6rem;
  border-radius: 34px 34px 0 0;
  border: 1px solid var(--lab-border);
  background: linear-gradient(180deg, rgba(251, 247, 240, 0.96), rgba(246, 240, 230, 0.98));
  box-shadow: var(--lab-shadow);
  overflow: hidden;
}

html[data-user-color-scheme="dark"] #board {
  background: linear-gradient(180deg, rgba(34, 26, 21, 0.94), rgba(24, 18, 15, 0.98));
}

.lab-home-board {
  position: relative;
  margin-top: -8rem;
  isolation: isolate;
}

.lab-home-board::before {
  content: "";
  position: absolute;
  top: 0;
  left: 8%;
  right: 8%;
  height: 8rem;
  transform: translateY(-58%);
  border-radius: 999px;
  background: radial-gradient(circle, rgba(244, 219, 168, 0.32) 0%, rgba(244, 219, 168, 0.1) 42%, transparent 74%);
  filter: blur(12px);
  pointer-events: none;
  z-index: 0;
}

.lab-home-board > .container {
  position: relative;
  z-index: 1;
}

.container,
.container-fluid,
.post-content,
.markdown-body {
  max-width: min(100%, var(--lab-content));
}

#navbar {
  backdrop-filter: blur(18px) saturate(1.1);
  background: rgba(32, 24, 18, 0.22);
  border-bottom: 1px solid transparent;
  transition: background var(--lab-mid) var(--lab-ease), border-color var(--lab-mid) var(--lab-ease), box-shadow var(--lab-mid) var(--lab-ease);
}

#navbar.is-scrolled {
  background: rgba(32, 24, 18, 0.86);
  border-color: rgba(255, 255, 255, 0.08);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.18);
}

.lab-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.9rem;
  color: #fff;
}

.lab-brand-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 3.4rem;
  min-height: 3.4rem;
  border-radius: 1.35rem;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 249, 241, 0.1);
  font-family: var(--lab-serif);
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.lab-brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.lab-brand-copy strong {
  font-size: 1.14rem;
  font-weight: 700;
  letter-spacing: 0.05em;
}

.lab-brand-copy small {
  margin-top: 0.2rem;
  font-size: 0.72rem;
  color: rgba(255, 244, 230, 0.6);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

#navbar .nav-link {
  color: rgba(255, 245, 232, 0.88);
}

#navbar .nav-link:hover,
#navbar .nav-link.active {
  color: #fff;
}

body.page-home #banner,
body.page-home .banner {
  min-height: calc(100svh - 1px);
}

#banner .mask {
  background: linear-gradient(180deg, rgba(20, 15, 12, 0.3), rgba(20, 15, 12, 0.58));
}

.banner-text--home {
  width: min(100%, var(--lab-content));
  margin: 0 auto;
  padding: 0 1.5rem;
}

.lab-hero {
  position: relative;
  max-width: 46rem;
  padding: clamp(1.8rem, 3vw, 2.8rem);
  border: 1px solid rgba(255, 244, 232, 0.14);
  border-radius: 2rem;
  background: linear-gradient(145deg, rgba(24, 18, 14, 0.86), rgba(24, 18, 14, 0.6));
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.22);
  backdrop-filter: blur(14px) saturate(1.06);
  color: #fff8f1;
  overflow: hidden;
}

.lab-hero::before {
  content: "";
  position: absolute;
  inset: 0 auto auto 0;
  width: 44%;
  height: 44%;
  background: radial-gradient(circle, rgba(244, 219, 168, 0.18), transparent 72%);
  pointer-events: none;
}

.lab-hero-eyebrow,
.lab-kicker {
  margin-bottom: 1rem;
  color: var(--lab-amber);
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.lab-hero-title {
  margin: 0;
  color: #fff8f1;
  font-size: clamp(2.8rem, 5vw, 5.5rem);
  line-height: 1.01;
  max-width: 10ch;
  position: relative;
  z-index: 1;
}

.lab-hero-summary {
  margin: 1.6rem 0 0;
  max-width: 32rem;
  color: rgba(255, 244, 232, 0.88);
  font-size: 1.05rem;
  position: relative;
  z-index: 1;
}

.lab-post-hero {
  width: min(100%, 62rem);
  margin: 0 auto;
  padding: clamp(0.5rem, 2vw, 1rem) 1.5rem 0;
  text-align: left;
}

.lab-post-hero-kicker {
  margin: 0 0 1rem;
  color: rgba(255, 238, 212, 0.72);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.lab-post-hero-title {
  margin: 0;
  color: #fff8f1;
  font-size: clamp(3rem, 6vw, 6rem);
  line-height: 0.96;
  letter-spacing: 0.02em;
  text-wrap: balance;
  text-shadow: 0 16px 40px rgba(0, 0, 0, 0.24);
}

.lab-post-hero-dek {
  max-width: 36rem;
  margin: 1.4rem 0 0;
  color: rgba(255, 244, 232, 0.82);
  font-size: 1.02rem;
  line-height: 1.9;
}

.lab-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin-top: 2rem;
  position: relative;
  z-index: 1;
}

.lab-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3.1rem;
  padding: 0 1.3rem;
  border-radius: 999px;
  border: 1px solid transparent;
  font-weight: 600;
  transition: transform var(--lab-fast) var(--lab-ease), box-shadow var(--lab-fast) var(--lab-ease), background var(--lab-fast) var(--lab-ease), color var(--lab-fast) var(--lab-ease);
}

.lab-button--primary {
  background: var(--lab-amber);
  color: #fffaf1;
  box-shadow: 0 12px 28px rgba(197, 138, 42, 0.28);
}

.lab-button--secondary {
  border-color: rgba(255, 244, 232, 0.18);
  background: rgba(255, 250, 241, 0.16);
  color: #fff8f1;
}

.lab-button:hover {
  transform: translateY(-2px);
}

.lab-button--primary:hover {
  color: #fffaf1;
  box-shadow: 0 16px 34px rgba(197, 138, 42, 0.34);
}

.lab-button--secondary:hover {
  color: #fff8f1;
  background: rgba(255, 250, 241, 0.2);
}

.lab-section {
  position: relative;
  padding: 4.5rem 0;
}

.lab-section + .lab-section {
  padding-top: 5.4rem;
  border-top: 0;
}

.lab-section + .lab-section::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(74, 56, 39, 0.18) 16%, rgba(74, 56, 39, 0.32) 50%, rgba(74, 56, 39, 0.18) 84%, transparent);
}

.lab-section + .lab-section::after {
  content: "";
  position: absolute;
  top: -0.36rem;
  left: 50%;
  width: 0.72rem;
  height: 0.72rem;
  margin-left: -0.36rem;
  border-radius: 50%;
  border: 1px solid rgba(197, 138, 42, 0.44);
  background: var(--lab-paper);
  box-shadow: 0 0 0 7px rgba(197, 138, 42, 0.08);
}

.lab-section-heading {
  max-width: 44rem;
  margin-bottom: 2rem;
}

.lab-section-heading h2 {
  margin-bottom: 0.9rem;
  font-size: clamp(1.8rem, 2.8vw, 3rem);
  line-height: 1.08;
}

.lab-section-heading p {
  margin-bottom: 0;
  font-size: 1rem;
}

.lab-featured {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  gap: 2rem;
  align-items: stretch;
}

.lab-home-bridge {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin: 0.8rem 0 1rem;
  opacity: 0.92;
}

.lab-home-bridge-line {
  width: clamp(4.5rem, 10vw, 8rem);
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(74, 56, 39, 0.28), rgba(197, 138, 42, 0.34), transparent);
}

.lab-home-bridge-mark {
  position: relative;
  width: 2.6rem;
  height: 2.6rem;
  border-radius: 50%;
  border: 1px solid rgba(74, 56, 39, 0.16);
  background: radial-gradient(circle at 50% 50%, rgba(197, 138, 42, 0.2), rgba(197, 138, 42, 0.04) 56%, transparent 58%);
  box-shadow: inset 0 0 0 0.4rem rgba(255, 255, 255, 0.2);
}

.lab-home-bridge-mark::before,
.lab-home-bridge-mark::after {
  content: "";
  position: absolute;
  border-radius: 50%;
}

.lab-home-bridge-mark::before {
  inset: 0.72rem;
  background: rgba(197, 138, 42, 0.46);
}

.lab-home-bridge-mark::after {
  inset: 0.34rem;
  border: 1px dashed rgba(197, 138, 42, 0.26);
}

.lab-featured-media img,
.lab-post-item-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border: 1px solid var(--lab-border);
  box-shadow: var(--lab-shadow);
}

.lab-featured-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 1rem 0;
}

.lab-featured-date,
.lab-post-item-meta,
.lab-timeline-item time {
  color: var(--lab-muted);
  font-size: 0.9rem;
  letter-spacing: 0.04em;
}

.lab-featured-content h3,
.lab-path h3,
.lab-post-item-content h3,
.evolution-stage h3,
.evolution-principles h3 {
  margin-bottom: 0.8rem;
  font-size: 2rem;
  line-height: 1.18;
}

.lab-featured-excerpt,
.lab-post-item-content p,
.lab-path p,
.lab-about-grid p {
  font-size: 1rem;
}

.lab-meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: 1.4rem;
}

.lab-chip {
  display: inline-flex;
  align-items: center;
  min-height: 2rem;
  padding: 0 0.8rem;
  border-radius: 999px;
  border: 1px solid var(--lab-border);
  background: var(--lab-paper-strong);
  color: var(--lab-olive);
  font-size: 0.9rem;
}

.lab-chip--link:hover {
  transform: translateY(-1px);
}

.lab-path-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.4rem;
}

.lab-path,
.lab-page-shell > .evolution-container > section,
.lab-post-header,
#toc,
#tocbot,
.toc-container,
.wl-card,
.wl-panel,
.wl-editor,
.wl-input {
  padding: 1.6rem;
  border-radius: var(--lab-radius-md);
  border: 1px solid var(--lab-border);
  background: rgba(251, 247, 240, 0.78);
  box-shadow: var(--lab-shadow);
}

html[data-user-color-scheme="dark"] .lab-path,
html[data-user-color-scheme="dark"] .lab-page-shell > .evolution-container > section,
html[data-user-color-scheme="dark"] .lab-post-header,
html[data-user-color-scheme="dark"] #toc,
html[data-user-color-scheme="dark"] #tocbot,
html[data-user-color-scheme="dark"] .toc-container,
html[data-user-color-scheme="dark"] .wl-card,
html[data-user-color-scheme="dark"] .wl-panel,
html[data-user-color-scheme="dark"] .wl-editor,
html[data-user-color-scheme="dark"] .wl-input {
  background: rgba(34, 26, 21, 0.76);
}

.lab-path-links {
  margin: 1.1rem 0 0;
  padding-left: 1.1rem;
}

.lab-path-links li + li {
  margin-top: 0.55rem;
}

.lab-recent-list {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.lab-post-item {
  position: relative;
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  gap: 1.55rem;
  align-items: stretch;
  padding: 1.35rem;
  border: 1px solid var(--lab-border);
  border-radius: 28px;
  background: linear-gradient(135deg, rgba(255, 251, 245, 0.92), rgba(246, 240, 230, 0.9));
  box-shadow: var(--lab-shadow);
  overflow: hidden;
}

.lab-post-item::before {
  content: "";
  position: absolute;
  top: 1rem;
  bottom: 1rem;
  left: 0;
  width: 5px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(197, 138, 42, 0.86), rgba(197, 138, 42, 0.26));
}

.lab-post-item::after {
  content: "";
  position: absolute;
  top: 1.1rem;
  right: 1.25rem;
  width: 4.8rem;
  height: 4.8rem;
  border-radius: 50%;
  background:
    radial-gradient(circle at 30% 35%, rgba(197, 138, 42, 0.24) 0.2rem, transparent 0.24rem),
    radial-gradient(circle at 68% 32%, rgba(65, 83, 70, 0.2) 0.18rem, transparent 0.22rem),
    radial-gradient(circle at 54% 72%, rgba(197, 138, 42, 0.18) 0.22rem, transparent 0.28rem);
  opacity: 0.9;
  pointer-events: none;
}

.lab-post-item-media {
  display: block;
  overflow: hidden;
  border-radius: var(--lab-radius-md);
  height: 100%;
}

.lab-post-item-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.45rem;
  padding: 0.2rem 0 0.1rem;
}

.lab-post-item-content h3 {
  font-size: 1.45rem;
  margin-bottom: 0.35rem;
}

.lab-post-item-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  margin-bottom: 0.4rem;
}

.lab-post-item-meta > * {
  display: inline-flex;
  align-items: center;
  min-height: 2rem;
  padding: 0 0.72rem;
  border-radius: 999px;
  border: 1px solid var(--lab-border);
  background: rgba(255, 255, 255, 0.46);
}

.lab-section--recent::before {
  content: "";
  position: absolute;
  top: 1.6rem;
  right: 0;
  width: 10rem;
  height: 1px;
  background: linear-gradient(90deg, rgba(197, 138, 42, 0), rgba(197, 138, 42, 0.28), rgba(197, 138, 42, 0));
}

html[data-user-color-scheme="dark"] .lab-post-item {
  background: linear-gradient(135deg, rgba(42, 33, 27, 0.9), rgba(30, 23, 18, 0.92));
}

html[data-user-color-scheme="dark"] .lab-post-item-meta > * {
  background: rgba(255, 255, 255, 0.06);
}

.lab-about-grid {
  display: grid;
  gap: 1rem;
}

.lab-inline-link {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  font-weight: 700;
}

.lab-listing {
  padding-top: 4.8rem;
}

.lab-category-grid,
.lab-tag-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.2rem;
}

.lab-category-card,
.lab-tag-card,
.lab-category-sidebar-group {
  border-radius: var(--lab-radius-md);
  border: 1px solid var(--lab-border);
  background: rgba(251, 247, 240, 0.82);
  box-shadow: var(--lab-shadow);
}

html[data-user-color-scheme="dark"] .lab-category-card,
html[data-user-color-scheme="dark"] .lab-tag-card,
html[data-user-color-scheme="dark"] .lab-category-sidebar-group {
  background: rgba(34, 26, 21, 0.78);
}

.lab-category-card {
  padding: 1.5rem;
}

.lab-category-card-head {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
}

.lab-category-card-head h3 {
  margin: 0;
  font-size: 1.55rem;
}

.lab-category-card-copy {
  margin: 1rem 0;
}

.lab-category-card-posts,
.lab-category-sidebar-posts {
  display: grid;
  gap: 0.7rem;
}

.lab-category-card-posts a,
.lab-category-sidebar-posts a,
.lab-tag-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  padding: 0.9rem 1rem;
  border-radius: 16px;
  border: 1px solid var(--lab-border);
  background: rgba(255, 253, 248, 0.72);
  color: var(--lab-ink);
}

html[data-user-color-scheme="dark"] .lab-category-card-posts a,
html[data-user-color-scheme="dark"] .lab-category-sidebar-posts a,
html[data-user-color-scheme="dark"] .lab-tag-card {
  background: rgba(42, 33, 27, 0.72);
}

.lab-category-card-posts a:hover,
.lab-category-sidebar-posts a:hover,
.lab-tag-card:hover {
  transform: translateY(-1px);
}

.lab-category-card-posts time,
.lab-tag-card-count,
.lab-category-sidebar-title span:last-child {
  color: var(--lab-muted);
  white-space: nowrap;
}

.lab-category-sidebar {
  display: grid;
  gap: 1rem;
}

.lab-category-sidebar-group {
  padding: 1rem;
}

.lab-category-sidebar-title {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.9rem;
  padding-bottom: 0.8rem;
  border-bottom: 1px solid var(--lab-border);
  color: var(--lab-ink);
  font-family: var(--lab-serif);
}

.lab-category-sidebar-posts a.is-active {
  border-color: var(--lab-amber);
  background: var(--lab-amber-soft);
}

.lab-tag-card-name {
  color: var(--lab-olive);
  font-weight: 700;
}

.lab-timeline {
  position: relative;
  padding-left: 2rem;
}

.lab-timeline::before {
  content: "";
  position: absolute;
  top: 0.6rem;
  bottom: 0.6rem;
  left: 0.4rem;
  width: 1px;
  background: var(--lab-border-strong);
}

.lab-timeline-year {
  position: relative;
  margin: 1.8rem 0 1rem;
}

.lab-timeline-year span {
  display: inline-flex;
  align-items: center;
  min-height: 2rem;
  padding: 0 0.75rem;
  border-radius: 999px;
  background: var(--lab-paper-strong);
  color: var(--lab-ink);
  font-weight: 700;
}

.lab-timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr);
  gap: 1rem;
  padding: 0.5rem 0 1rem;
}

.lab-timeline-item::before {
  content: "";
  position: absolute;
  top: 0.8rem;
  left: -1.86rem;
  width: 0.8rem;
  height: 0.8rem;
  border-radius: 50%;
  background: var(--lab-amber);
  box-shadow: 0 0 0 5px var(--lab-amber-soft);
}

.lab-timeline-entry {
  display: grid;
  gap: 0.7rem;
}

.lab-timeline-entry > a {
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-size: 1.18rem;
}

.lab-timeline-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
}

.lab-page-content {
  max-width: min(100%, 980px);
  margin: 0 auto;
  padding: 4rem 0 1rem;
}

.lab-page-shell {
  display: grid;
  gap: 1.4rem;
}

.evolution-container {
  display: grid;
  gap: 1.4rem;
}

.evolution-intro h2,
.evolution-focus h3,
.evolution-timeline h3,
.evolution-principles h3 {
  margin-bottom: 1rem;
}

.evolution-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.evolution-stage {
  padding: 1.3rem;
  border-radius: var(--lab-radius-sm);
  background: var(--lab-paper);
  border: 1px solid var(--lab-border);
}

.evolution-stage p {
  margin-bottom: 0;
}

.evolution-timeline-header {
  max-width: 42rem;
  margin-bottom: 2rem;
}

.evolution-timeline-header > p:last-child {
  margin-bottom: 0;
}

.evolution-history {
  display: grid;
  gap: 2rem;
}

.evolution-era {
  display: grid;
  gap: 1.1rem;
}

.evolution-era + .evolution-era {
  padding-top: 1.8rem;
  border-top: 1px solid var(--lab-border);
}

.evolution-era-label {
  display: grid;
  gap: 0.55rem;
}

.evolution-era-label span {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  min-height: 2rem;
  padding: 0 0.8rem;
  border-radius: 999px;
  background: var(--lab-amber-soft);
  color: var(--lab-amber);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.evolution-era-label h4 {
  margin: 0;
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-size: 1.5rem;
}

.evolution-era-items {
  position: relative;
  display: grid;
  gap: 1.25rem;
  padding-left: 1.6rem;
}

.evolution-era-items::before {
  content: "";
  position: absolute;
  top: 0.2rem;
  bottom: 0.2rem;
  left: 0.35rem;
  width: 1px;
  background: linear-gradient(180deg, rgba(197, 138, 42, 0.1), rgba(197, 138, 42, 0.34), rgba(74, 56, 39, 0.14));
}

.evolution-milestone {
  position: relative;
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  gap: 1.1rem;
  align-items: start;
}

.evolution-milestone::before {
  content: "";
  position: absolute;
  top: 0.55rem;
  left: -1.33rem;
  width: 0.82rem;
  height: 0.82rem;
  border-radius: 50%;
  background: var(--lab-amber);
  box-shadow: 0 0 0 5px var(--lab-amber-soft);
}

.evolution-milestone-date {
  color: var(--lab-amber);
  font-weight: 700;
  letter-spacing: 0.04em;
}

.evolution-milestone-body {
  display: grid;
  gap: 0.45rem;
  padding: 0.05rem 0 1.15rem;
  border-bottom: 1px solid rgba(74, 56, 39, 0.1);
}

.evolution-milestone:last-child .evolution-milestone-body {
  padding-bottom: 0;
  border-bottom: 0;
}

.evolution-milestone-title {
  margin: 0;
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-size: 1.22rem;
  line-height: 1.2;
}

.evolution-milestone-summary {
  margin: 0;
  color: var(--lab-muted);
}

.evolution-outlook {
  margin-top: 0.2rem;
  padding: 1.5rem;
  border-radius: var(--lab-radius-md);
  border: 1px solid rgba(197, 138, 42, 0.24);
  background: linear-gradient(135deg, rgba(197, 138, 42, 0.08), rgba(255, 255, 255, 0.26));
  box-shadow: var(--lab-shadow);
}

.evolution-outlook h4 {
  margin: 0 0 0.7rem;
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-size: 1.35rem;
}

.evolution-outlook p {
  margin: 0;
}

html[data-user-color-scheme="dark"] .evolution-outlook {
  background: linear-gradient(135deg, rgba(197, 138, 42, 0.1), rgba(42, 33, 27, 0.78));
  border-color: rgba(197, 138, 42, 0.26);
}

.evolution-principles ul {
  margin: 0;
  padding-left: 1.2rem;
}

.evolution-principles li + li {
  margin-top: 0.6rem;
}

body.page-post #board-ctn.container {
  width: min(100%, var(--lab-post-shell));
  max-width: min(100%, var(--lab-post-shell));
}

body.page-post #banner,
body.page-post .banner {
  min-height: clamp(28rem, 68vh, 42rem);
}

body.page-post #banner .mask {
  background:
    linear-gradient(180deg, rgba(18, 14, 11, 0.18) 0%, rgba(18, 14, 11, 0.5) 42%, rgba(18, 14, 11, 0.84) 100%),
    linear-gradient(135deg, rgba(197, 138, 42, 0.12), transparent 38%);
}

body.page-post .banner-text {
  width: min(100%, var(--lab-post-shell));
  margin: 0 auto;
  padding: clamp(7rem, 14vw, 10rem) 1.5rem clamp(8rem, 16vw, 11rem);
}

body.page-post #board {
  margin-top: calc(var(--lab-post-overlap) * -1);
  padding: 0 0 4rem;
  border: 0;
  border-radius: 2.8rem 2.8rem 0 0;
  background: transparent;
  box-shadow: none;
  overflow: visible;
}

body.page-post .post-content {
  max-width: min(100%, var(--lab-post-shell));
  padding: 0 1.5rem 1rem;
}

.lab-post-header {
  margin: 1.8rem 0 2.2rem;
}

body.page-post .lab-post-intro {
  position: relative;
  z-index: 2;
  width: min(100%, calc(var(--lab-post-reading) + 1rem));
  margin: 0 0 2rem;
  padding: clamp(1.35rem, 2.8vw, 2rem);
  border-radius: 2rem;
  border: 1px solid rgba(74, 56, 39, 0.12);
  background:
    linear-gradient(135deg, rgba(255, 252, 247, 0.84), rgba(244, 235, 221, 0.92)),
    url("/img/lab/texture-grain.svg");
  box-shadow: 0 18px 50px rgba(32, 24, 18, 0.08);
  backdrop-filter: blur(14px);
}

html[data-user-color-scheme="dark"] body.page-post .lab-post-intro,
html[data-user-color-scheme="dark"] .page-post .lab-post-intro {
  background:
    linear-gradient(135deg, rgba(42, 33, 27, 0.84), rgba(31, 23, 18, 0.94)),
    url("/img/lab/texture-grain.svg");
}

.lab-post-header-meta .mt-3,
.lab-post-header-meta .mt-1,
.post-metas.my-3 {
  margin: 0 !important;
}

.lab-post-header-meta {
  display: grid;
  gap: 0.85rem;
}

.lab-post-meta-line {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.lab-post-summary {
  margin: 1.1rem 0 0;
  font-size: 1.02rem;
}

body.page-post .lab-post-summary {
  max-width: 50rem;
  margin-top: 1rem;
  color: var(--lab-ink);
  font-size: 1.08rem;
  line-height: 1.92;
}

body.page-post .post-metas.my-3 {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem 1rem;
}

body.page-post .post-metas .post-meta {
  margin-right: 0;
}

body.page-post .post-metas .post-meta a {
  display: inline-flex;
  align-items: center;
  margin: 0.15rem 0.45rem 0.15rem 0;
  padding: 0.1rem 0.55rem;
  border-radius: 999px;
  background: rgba(197, 138, 42, 0.1);
  color: var(--lab-olive);
  font-size: 0.88rem;
}

body.page-post .post-metas .post-meta a:last-child {
  margin-right: 0;
}

body.page-post #updated-time {
  width: fit-content;
  margin: 0 0 1.5rem;
}

body.page-post .lab-post-body-layout {
  display: grid;
  grid-template-columns: minmax(0, var(--lab-post-reading)) minmax(220px, var(--lab-post-aside));
  gap: var(--lab-post-gap);
  align-items: start;
}

body.page-post .lab-post-main {
  min-width: 0;
}

body.page-post .lab-post-paper {
  position: relative;
  padding: clamp(1.6rem, 3vw, 2.8rem);
  border-radius: 2.2rem;
  border: 1px solid rgba(74, 56, 39, 0.12);
  background:
    linear-gradient(180deg, rgba(255, 252, 247, 0.97), rgba(248, 241, 232, 0.98)),
    url("/img/lab/texture-grain.svg");
  box-shadow: 0 18px 50px rgba(32, 24, 18, 0.08);
}

body.page-post .lab-post-paper::before {
  content: "";
  position: absolute;
  top: 1.1rem;
  left: 1.2rem;
  right: 1.2rem;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(197, 138, 42, 0.36), transparent);
  opacity: 0.72;
  pointer-events: none;
}

html[data-user-color-scheme="dark"] body.page-post .lab-post-paper,
html[data-user-color-scheme="dark"] .page-post .lab-post-paper {
  background:
    linear-gradient(180deg, rgba(37, 29, 24, 0.97), rgba(28, 21, 17, 0.98)),
    url("/img/lab/texture-grain.svg");
}

body.page-post .lab-post-tail {
  display: grid;
  gap: 1.2rem;
  margin-top: 1.6rem;
}

body.page-post .lab-post-divider {
  margin: 0.1rem 0 0;
}

body.page-post .lab-post-rail {
  min-width: 0;
}

body.page-post .lab-post-sidebar {
  position: static;
  padding: 0;
}

body.page-post .lab-seo-header {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.post-content .markdown-body,
.markdown-body {
  color: var(--lab-ink);
  font-size: 1.03rem;
  line-height: 1.92;
}

.post-content .markdown-body p,
.post-content .markdown-body li,
.markdown-body p,
.markdown-body li {
  color: var(--lab-muted);
}

.post-content .markdown-body h1,
.post-content .markdown-body h2,
.post-content .markdown-body h3,
.markdown-body h1,
.markdown-body h2,
.markdown-body h3 {
  margin-top: 2.4rem;
  margin-bottom: 1rem;
}

.markdown-body blockquote {
  margin: 1.8rem 0;
  padding: 1rem 1.2rem 1rem 1.4rem;
  border-left: 3px solid var(--lab-amber);
  background: rgba(197, 138, 42, 0.08);
  color: var(--lab-ink);
}

.markdown-body code {
  border-radius: 0.5rem;
  padding: 0.1em 0.35em;
  background: var(--lab-amber-soft);
  color: var(--lab-ink);
}

.markdown-body pre,
.markdown-body .hljs {
  border-radius: var(--lab-radius-md);
  border: 1px solid var(--lab-border);
  background: rgba(34, 26, 21, 0.95);
}

.markdown-body img {
  border: 1px solid var(--lab-border);
  box-shadow: var(--lab-shadow);
}

body.page-post #toc,
body.page-post #tocbot,
body.page-post .toc-container {
  position: sticky;
  top: 6rem;
  padding: 1.35rem 1.2rem 1.4rem;
  border-radius: 1.6rem;
  border: 1px solid rgba(74, 56, 39, 0.12);
  background: rgba(251, 247, 240, 0.58);
  box-shadow: none;
  backdrop-filter: blur(12px);
}

body.page-post #toc .toc-header {
  margin-bottom: 0.8rem;
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-weight: 700;
}

body.page-post #toc .toc-header span {
  letter-spacing: 0.08em;
}

body.page-post #toc a,
body.page-post #tocbot a,
body.page-post .toc-container a {
  color: var(--lab-muted);
}

body.page-post #toc a:hover,
body.page-post #tocbot a:hover,
body.page-post .toc-container a:hover,
body.page-post .tocbot-active-link {
  color: var(--lab-olive) !important;
}

body.page-post #toc .toc-body {
  max-height: calc(100vh - 9rem);
  padding-right: 0.2rem;
}

body.page-post #toc .toc-list-item {
  display: block;
  padding: 0.22rem 0;
  overflow: visible;
  -webkit-line-clamp: initial;
}

body.page-post #toc .tocbot-link {
  display: block;
  padding: 0.15rem 0 0.15rem 0.8rem;
  border-left: 1px solid transparent;
  font-size: 0.95rem;
  line-height: 1.55;
}

body.page-post #toc .tocbot-list ol {
  padding-left: 0.95rem;
}

body.page-post #toc .tocbot-list ol .tocbot-link {
  font-size: 0.88rem;
  opacity: 0.88;
}

body.page-post #toc .tocbot-active-link {
  border-left-color: rgba(197, 138, 42, 0.8);
  color: var(--lab-ink) !important;
  font-weight: 700;
}

body.page-post #toc .toc-list-item::before {
  left: 0.1rem;
}

body.page-post .license-box,
body.page-post .post-prevnext,
body.page-post #comments {
  border: 1px solid var(--lab-border);
  border-radius: var(--lab-radius-md);
  background: rgba(251, 247, 240, 0.78);
  box-shadow: none;
}

body.page-post .license-box,
body.page-post .post-prevnext {
  padding: 1.15rem 1.25rem;
}

body.page-post #comments {
  margin-top: 0;
  padding: 1.25rem;
}

.pagination .page-link,
#scroll-top-button {
  border-radius: 999px;
  border: 1px solid var(--lab-border);
  background: rgba(251, 247, 240, 0.92);
  color: var(--lab-ink);
}

#scroll-top-button:hover,
.pagination .page-item.active .page-link {
  background: var(--lab-amber);
  color: #fff;
  border-color: var(--lab-amber);
}

.wl-btn {
  border-radius: 999px !important;
  border-color: var(--lab-amber) !important;
  background: var(--lab-amber-soft) !important;
  color: var(--lab-ink) !important;
}

.lab-footer {
  padding: 2.5rem 1rem 3rem;
}

.lab-footer-content {
  display: grid;
  gap: 0.7rem;
  justify-items: center;
  text-align: center;
}

.lab-footer-title {
  margin: 0;
  color: var(--lab-ink);
  font-family: var(--lab-serif);
  font-size: 1.1rem;
}

.lab-footer-text {
  margin: 0;
  max-width: 40rem;
}

.lab-footer-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
}

.kb-reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 520ms var(--lab-ease), transform 520ms var(--lab-ease);
}

.kb-reveal.is-inview {
  opacity: 1;
  transform: translateY(0);
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible {
  outline: 2px solid var(--lab-amber);
  outline-offset: 3px;
}

@media (max-width: 1199px) {
  #board {
    margin-top: -4rem;
  }

  .lab-featured,
  .lab-path-grid,
  .evolution-grid,
  .lab-category-grid,
  .lab-tag-grid {
    grid-template-columns: 1fr;
  }

  .lab-post-item {
    grid-template-columns: 180px minmax(0, 1fr);
  }

  body.page-post #board {
    margin-top: calc(var(--lab-post-overlap) * -0.72);
  }

  body.page-post .lab-post-body-layout {
    grid-template-columns: 1fr;
    gap: 1.4rem;
  }

  body.page-post .lab-post-rail {
    order: -1;
  }

  body.page-post #toc,
  body.page-post #tocbot,
  body.page-post .toc-container {
    position: relative;
    top: 0;
  }
}

@media (max-width: 768px) {
  body.page-home #banner,
  body.page-home .banner {
    min-height: 86svh;
  }

  #board {
    margin-top: -2.5rem;
    border-radius: 28px 28px 0 0;
  }

  .lab-home-board {
    margin-top: -3.4rem;
  }

  .lab-brand-mark {
    min-width: 3.5rem;
    min-height: 3.5rem;
    font-size: 0.82rem;
  }

  .lab-brand-copy small {
    display: none;
  }

  .lab-section {
    padding: 3.2rem 0;
  }

  .lab-post-item,
  .evolution-milestone,
  .lab-timeline-item {
    grid-template-columns: 1fr;
  }

  .lab-hero {
    padding: 1.5rem;
    border-radius: 1.6rem;
  }

  .lab-home-bridge {
    margin: 0.3rem 0 0.8rem;
    gap: 0.8rem;
  }

  .lab-home-bridge-mark {
    width: 2.2rem;
    height: 2.2rem;
  }

  .lab-section + .lab-section {
    padding-top: 4.2rem;
  }

  .lab-post-item {
    gap: 1rem;
    padding: 1rem;
  }

  .evolution-era-items {
    padding-left: 1.2rem;
  }

  .evolution-milestone {
    gap: 0.45rem;
  }

  .evolution-milestone-date {
    display: inline-flex;
    width: fit-content;
    min-height: 1.8rem;
    padding: 0 0.65rem;
    border-radius: 999px;
    background: var(--lab-amber-soft);
  }

  .evolution-milestone-body {
    padding-bottom: 1rem;
  }

  .lab-category-card-posts a,
  .lab-tag-card {
    align-items: flex-start;
    flex-direction: column;
  }

  .lab-post-item-media img {
    min-height: 220px;
  }

  .lab-page-content {
    padding-top: 2.8rem;
  }

  body.page-post #banner,
  body.page-post .banner {
    min-height: 32rem;
  }

  body.page-post .banner-text {
    padding: 6.2rem 1rem 6.4rem;
  }

  body.page-post #board {
    margin-top: -2rem;
    padding-bottom: 2.8rem;
  }

  body.page-post .post-content {
    padding: 0 1rem 1rem;
  }

  body.page-post .lab-post-intro,
  body.page-post .lab-post-paper,
  body.page-post #toc,
  body.page-post #tocbot,
  body.page-post .toc-container {
    padding: 1.25rem;
  }

  body.page-post .lab-post-hero-title {
    font-size: clamp(2.6rem, 10vw, 4rem);
  }

  body.page-post .lab-post-hero-dek {
    font-size: 0.98rem;
  }
}

@media (max-width: 480px) {
  .lab-hero-title {
    font-size: 2.5rem;
  }

  .lab-hero-actions {
    flex-direction: column;
  }

  .lab-button {
    width: 100%;
  }

  .lab-home-bridge {
    gap: 0.6rem;
  }

  .lab-home-bridge-line {
    width: 3.2rem;
  }

  .lab-post-item {
    padding: 0.95rem;
    border-radius: 24px;
  }

  .evolution-era {
    gap: 0.9rem;
  }

  .evolution-era-label h4 {
    font-size: 1.28rem;
  }

  .evolution-outlook {
    padding: 1.2rem;
  }

  .lab-hero-summary,
  .lab-post-summary,
  .lab-post-item-content p,
  .lab-path p {
    font-size: 0.96rem;
  }

  .lab-path,
  .lab-page-shell > .evolution-container > section,
  .lab-post-header,
  #toc,
  #tocbot,
  .toc-container {
    padding: 1.2rem;
  }

  body.page-post #banner,
  body.page-post .banner {
    min-height: 28rem;
  }

  body.page-post .banner-text {
    padding: 5.8rem 1rem 5.3rem;
  }

  body.page-post .lab-post-hero-title {
    font-size: 2.45rem;
  }

  body.page-post .lab-post-hero-dek,
  body.page-post .lab-post-summary {
    font-size: 0.95rem;
  }

  body.page-post .lab-post-intro,
  body.page-post .lab-post-paper,
  body.page-post #toc,
  body.page-post #tocbot,
  body.page-post .toc-container {
    padding: 1.05rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }

  .kb-reveal {
    opacity: 1 !important;
    transform: none !important;
  }
}

Page._content:
:root {
  color-scheme: light;
  --lab-bg: #f6f0e6;
  --lab-paper: #fbf7f0;
  --lab-paper-strong: #fffdf8;
  --lab-ink: #201812;
  --lab-muted: #6d5e53;
  --lab-amber: #c58a2a;
  --lab-olive: #415346;
  --lab-border: rgba(74, 56, 39, 0.14);
  --lab-shadow: 0 18px 40px rgba(32, 24, 18, 0.08);
  --lab-radius-lg: 18px;
  --lab-radius-md: 14px;
  --lab-radius-sm: 10px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  line-height: 1.8;
  color: var(--lab-ink);
  background: radial-gradient(circle at top, rgba(197, 138, 42, 0.12), transparent 46%), var(--lab-bg);
  min-height: 100vh;
}

a {
  color: var(--lab-olive);
  text-decoration: none;
}

a:hover {
  color: var(--lab-amber);
}

.page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.lab-brandbar {
  background: rgba(251, 247, 240, 0.92);
  border-bottom: 1px solid var(--lab-border);
  backdrop-filter: blur(12px);
}

.lab-brandbar__inner {
  max-width: 980px;
  margin: 0 auto;
  padding: 14px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.lab-brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.lab-brand__mark {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: #201812;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.lab-brand__mark img {
  width: 24px;
  height: 24px;
}

.lab-brand__name {
  font-family: "Noto Serif SC", "Songti SC", "STSong", serif;
  font-size: 18px;
  letter-spacing: 0.04em;
}

.lab-brand__meta {
  font-size: 12px;
  color: var(--lab-muted);
}

.lab-return {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--lab-olive);
  border-bottom: 1px solid transparent;
}

.lab-return:hover {
  border-color: var(--lab-amber);
}

.container {
  max-width: 980px;
  margin: 0 auto;
  padding: 28px 20px 56px;
  width: 100%;
}

.doc-header,
.section,
.card,
.doc-list a {
  background: var(--lab-paper);
  border-radius: var(--lab-radius-lg);
  border: 1px solid var(--lab-border);
  box-shadow: var(--lab-shadow);
}

.doc-header {
  padding: 28px 28px 22px;
  margin-bottom: 24px;
}

.doc-header h1 {
  font-family: "Noto Serif SC", "Songti SC", "STSong", serif;
  font-size: 30px;
  margin-bottom: 8px;
}

.doc-header .app-name,
.doc-header .update-date,
.sub {
  color: var(--lab-muted);
  font-size: 13px;
}

.section,
.card {
  padding: 24px 26px;
  margin-bottom: 18px;
}

.section h2,
.card h2 {
  font-family: "Noto Serif SC", "Songti SC", "STSong", serif;
  font-size: 20px;
  margin-bottom: 12px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--lab-border);
}

.section p,
.card p,
li {
  color: var(--lab-muted);
}

.section p,
.card p {
  margin-bottom: 12px;
}

ul {
  margin-left: 20px;
  margin-bottom: 12px;
}

li {
  margin-bottom: 8px;
}

strong {
  color: var(--lab-ink);
}

.highlight-box,
.tip {
  background: rgba(197, 138, 42, 0.12);
  border-left: 4px solid var(--lab-amber);
  padding: 14px 18px;
  border-radius: 0 var(--lab-radius-sm) var(--lab-radius-sm) 0;
  margin-top: 12px;
}

.highlight-box p,
.tip p {
  color: var(--lab-olive);
  margin-bottom: 0;
}

.data-item {
  background: rgba(65, 83, 70, 0.08);
  padding: 12px 16px;
  border-radius: var(--lab-radius-sm);
  margin-bottom: 12px;
}

.permission-table {
  width: 100%;
  border-collapse: collapse;
  margin: 14px 0;
}

.permission-table th,
.permission-table td {
  padding: 12px 16px;
  text-align: left;
  border-bottom: 1px solid var(--lab-border);
}

.permission-table th {
  background: rgba(65, 83, 70, 0.08);
  color: var(--lab-ink);
}

.permission-table td {
  color: var(--lab-muted);
}

.contact-info {
  background: rgba(65, 83, 70, 0.08);
  padding: 18px;
  border-radius: var(--lab-radius-md);
  text-align: center;
}

.doc-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.doc-list a {
  display: grid;
  gap: 10px;
  padding: 22px;
}

.doc-list h2 {
